            model: 'gpt-5.5',
            prompt: `Run ${id}`,
            type: 'agent',
            ...overrides,
        }),
        path: `actions/${id}.json`,
    };
}

function successfulAgentResult(request) {
    return { command: request.command, exitCode: 0, prompt: request.prompt, stderr: '', stdout: 'done' };
}

